void restart_mab(kissat *solver) {
    // State variables to maintain algorithm progress across restarts
    static double Q[2] = {0.0, 0.0};
    static double V[2] = {0.0, 0.0};
    static double LBD_prev = 0.0;
    static unsigned consecutive_count = 0;
    static uint64_t last_ticks = 0;
    static bool initialized = false;

    // Capture current phase metrics
    double avg_LBD = AVERAGE(fast_glue);
    if (avg_LBD < 1.0) avg_LBD = 1.0; // Avoid division by zero and ensure quality baseline

    // Initialization for the first run
    if (!initialized) {
        LBD_prev = avg_LBD;
        last_ticks = solver->ticks;
        initialized = true;
    }

    // Step 1: Compute Phase Reward R
    // R = log2(conflicts + 1) / ((ticks + 1) * avg_LBD)
    uint64_t current_ticks = solver->ticks;
    uint64_t elapsed_ticks = (current_ticks > last_ticks) ? (current_ticks - last_ticks) : 0;
    last_ticks = current_ticks;

    double R = log2((double)solver->mab_conflicts + 1.0) / (((double)elapsed_ticks + 1.0) * avg_LBD);

    // Step 2: Update Quality (Q) and Volatility (V) using EMA (alpha=0.2)
    unsigned mode = solver->heuristic;
    if (mode > 1) mode = 0; // Ensure mode is within expected binary bounds

    Q[mode] = 0.8 * Q[mode] + 0.2 * R;
    double diff = R - Q[mode];
    if (diff < 0) diff = -diff; // Absolute difference |R - Q_new|
    V[mode] = 0.8 * V[mode] + 0.2 * diff;

    // Step 3: Calculate Normalized LBD Momentum M
    // M = (LBD_prev - avg_LBD_curr) / LBD_prev
    double M = (LBD_prev > 0) ? (LBD_prev - avg_LBD) / LBD_prev : 0.0;
    LBD_prev = avg_LBD;

    // Step 4: Apply Momentum Gating
    unsigned next_mode = mode;
    bool gating_applied = false;
    if (solver->mab_conflicts > 512) {
        if (M > 0.05) {
            // LBD improving by >5%, stay in current mode
            next_mode = mode;
            gating_applied = true;
        } else if (M < -0.10) {
            // LBD worsening by >10%, switch to other mode
            next_mode = 1 - mode;
            gating_applied = true;
        }
    }

    // Step 5: Selection Score S calculation (if no gating applies)
    if (!gating_applied) {
        unsigned other = 1 - mode;
        // S = (Q * (0.98 ^ consecutive_count)) / (1.0 + V)
        double S_mode = (Q[mode] * pow(0.98, (double)consecutive_count)) / (1.0 + V[mode]);
        double S_other = Q[other] / (1.0 + V[other]); // consecutive_count for inactive mode is 0

        if (S_other > S_mode) {
            next_mode = other;
        } else {
            next_mode = mode;
        }
    }

    // Update consecutive count based on whether the mode changed
    if (next_mode != mode) {
        consecutive_count = 0;
    } else {
        consecutive_count++;
    }

    // Apply the selection to the solver
    solver->heuristic = next_mode;
    solver->mab_select[next_mode]++;

    // Standard Kissat MAB cleanup: Reset phase-specific tracking counters
    solver->mab_decisions = 0;
    solver->mab_conflicts = 0;
    solver->mab_chosen_tot = 0;
    for (all_variables (idx)) {
        solver->mab_chosen[idx] = 0;
    }
}

