void restart_mab(kissat *solver) {
    // Step 1: Calculate Phase Metrics and Progress Weight
    static double best_lbd = 1e100;
    static unsigned best_assigned_trail = 0xFFFFFFFF;
    static int stagnation_counter = 0;
    static int phases_since_switch = 0;
    static double mu_LBD = 0.0;
    static double prev_LBD = 0.0;
    static double mu_rate = 0.0;
    static double V = 0.0;

    const double alpha = 0.2;
    double avg_lbd = AVERAGE(fast_glue);
    if (avg_lbd < 1.0) avg_lbd = 1.0;

    bool improved = false;
    if (avg_lbd < best_lbd) {
        best_lbd = avg_lbd;
        improved = true;
    }
    if (solver->unassigned < best_assigned_trail) {
        best_assigned_trail = solver->unassigned;
        improved = true;
    }

    double R = log2(1.0 + (double)solver->mab_conflicts) / avg_lbd;
    if (improved) {
        R *= 1.5;
    } else {
        R *= 0.8;
    }

    // Step 2: Update Quality Q_m and Mean LBD using EMA
    unsigned m = solver->heuristic;
    solver->mab_reward[m] = (1.0 - alpha) * solver->mab_reward[m] + alpha * R;

    if (mu_LBD == 0.0) {
        mu_LBD = avg_lbd;
    } else {
        mu_LBD = (1.0 - alpha) * mu_LBD + alpha * avg_lbd;
    }

    double current_rate = (solver->mab_decisions > 0) ? (double)solver->mab_conflicts / (double)solver->mab_decisions : 0.0;
    if (mu_rate == 0.0 && current_rate > 0) mu_rate = current_rate;
    double deviation = fabs(current_rate - mu_rate);
    V = (1.0 - alpha) * V + alpha * deviation;
    mu_rate = (1.0 - alpha) * mu_rate + alpha * current_rate;

    // Step 3: Calculate Scale-Invariant Momentum and Stagnation
    if (prev_LBD == 0.0) prev_LBD = avg_lbd;
    double S_norm = (avg_lbd - prev_LBD) / (mu_LBD > 1e-6 ? mu_LBD : 1.0);
    prev_LBD = avg_lbd;

    if (!improved) {
        stagnation_counter++;
    }

    // Step 4: Decision Gating
    phases_since_switch++;
    unsigned next_m = m;
    bool boltzmann_active = false;

    if (phases_since_switch < 3) {
        next_m = m;
    } else if (S_norm < -0.05) {
        next_m = m;
    } else if (S_norm > 0.05 && stagnation_counter > 5) {
        next_m = (m + 1) % solver->mab_heuristics;
    } else if (fabs(S_norm) <= 0.05) {
        boltzmann_active = true;
    }

    // Step 5: Adaptive Boltzmann Selection
    if (boltzmann_active) {
        double T = 0.1 + V;
        double max_q_t = -1e100;

        // Find max exponent for numerical stability
        for (unsigned i = 0; i < solver->mab_heuristics; i++) {
            double val = solver->mab_reward[i] / T;
            if (val > max_q_t) max_q_t = val;
        }

        double sum_exp = 0.0;
        for (unsigned i = 0; i < solver->mab_heuristics; i++) {
            sum_exp += exp((solver->mab_reward[i] / T) - max_q_t);
        }

        if (sum_exp > 0) {
            double r = kissat_pick_double(&solver->random);
            double cumulative_p = 0.0;
            for (unsigned i = 0; i < solver->mab_heuristics; i++) {
                double p = exp((solver->mab_reward[i] / T) - max_q_t) / sum_exp;
                cumulative_p += p;
                if (r < cumulative_p) {
                    next_m = i;
                    break;
                }
            }
        }
    }

    // Reset stagnation and cooldown on mode switch
    if (next_m != m) {
        stagnation_counter = 0;
        phases_since_switch = 0;
    }

    // Apply selection and update housekeeping
    solver->heuristic = next_m;
    solver->mab_select[next_m]++;

    unsigned idx;
    for (all_variables(idx)) {
        solver->mab_chosen[idx] = 0;
    }
    solver->mab_chosen_tot = 0;
    solver->mab_conflicts = 0;
    solver->mab_decisions = 0;
}

