#include <math.h>
#include <stdbool.h>
#include <stdint.h>
#include <inttypes.h>

#define MAB_ALPHA_FAST 0.2
#define MAB_ALPHA_SLOW 0.05
#define MAB_ALPHA_VOL 0.1
#define MAB_M_THRESHOLD 0.05
#define MAB_M_PROB_SCALE 2.5
#define MAB_PERF_MARGIN 0.95
#define MAB_T_BASE 0.1
#define MAB_EPSILON 1e-6

void restart_mab(kissat *solver) {
    // Step 1: Calculate the interval performance metric P
    // P = (conflicts / decisions) * (1.0 / (average_LBD + 1.0))
    const double conflicts = (double)solver->mab_conflicts;
    const double decisions = (double)solver->mab_decisions;
    const double avg_lbd = AVERAGE(fast_glue);
    const double P = (decisions > 0) ? (conflicts / decisions) * (1.0 / (avg_lbd + 1.0)) : 0.0;

    // Step 2: Update EMAs and volatility measure V for the active mode
    // E_fast (alpha=0.2), E_slow (alpha=0.05), V (alpha=0.1)
    // Static arrays are used to persist state across calls as the kissat struct is fixed.
    static double e_fast[2] = {0.0, 0.0};
    static double e_slow[2] = {0.0, 0.0};
    static double volatility[2] = {0.0, 0.0};
    static bool initialized[2] = {false, false};

    const unsigned m = solver->heuristic;
    if (m >= 2) return; // Safety check: Kissat MAB typically uses 2 heuristics (0 and 1)

    if (!initialized[m]) {
        e_fast[m] = P;
        e_slow[m] = P;
        volatility[m] = 0.0;
        initialized[m] = true;
    } else {
        e_fast[m] = (1.0 - MAB_ALPHA_FAST) * e_fast[m] + MAB_ALPHA_FAST * P;
        e_slow[m] = (1.0 - MAB_ALPHA_SLOW) * e_slow[m] + MAB_ALPHA_SLOW * P;
        volatility[m] = (1.0 - MAB_ALPHA_VOL) * volatility[m] + MAB_ALPHA_VOL * fabs(P - e_fast[m]);
    }

    // Update solver->mab_reward for reporting and external visibility
    solver->mab_reward[m] = e_fast[m];

    // Step 3: Compute the Relative Momentum M
    // M = (E_fast - E_slow) / (E_slow + 1e-6)
    const double M = (e_fast[m] - e_slow[m]) / (e_slow[m] + MAB_EPSILON);

    unsigned next_m = m;
    const unsigned other = 1 - m;

    // Step 4: Apply Trajectory Gating
    if (M > M_M_THRESHOLD) {
        // Improving: deterministically stay in current mode
        next_m = m;
    } else if (M < -M_M_THRESHOLD) {
        // Degrading: check if the other mode's baseline performance is significantly better
        if (initialized[other] && e_fast[m] < (e_fast[other] * MAB_PERF_MARGIN)) {
            double prob = fabs(M) * M_PROB_SCALE;
            if (prob > 1.0) prob = 1.0;
            if (kissat_pick_double(&solver->random) < prob) {
                next_m = other;
            }
        }
    } else {
        // Step 5: Stagnant (|M| <= 0.05): Apply Volatility-Scaled Boltzmann Selection
        // Temperature T = 0.1 + (V / (E_fast + 1e-6))
        const double T = MAB_T_BASE + (volatility[m] / (e_fast[m] + MAB_EPSILON));

        // Compute probabilities P(m) = exp(E_fast_m / T) / Sum(exp(E_fast_k / T))
        // Use max-subtraction for numerical stability with exp()
        const double v0 = e_fast[0] / T;
        const double v1 = e_fast[1] / T;
        const double max_v = (v0 > v1) ? v0 : v1;

        const double exp0 = exp(v0 - max_v);
        const double exp1 = exp(v1 - max_v);
        const double sum_exp = exp0 + exp1;

        if (sum_exp > 0) {
            const double prob0 = exp0 / sum_exp;
            const double r = kissat_pick_double(&solver->random);
            next_m = (r < prob0) ? 0 : 1;
        }
    }

    // Apply the selection to the solver state
    solver->heuristic = next_m;
    solver->mab_select[next_m]++;

    // Reset interval counters for the next restart phase
    solver->mab_decisions = 0;
    solver->mab_conflicts = 0;
}

