void restart_mab(kissat *solver) {
    // Persistent state for the dual EMA and selection logic
    static double S_fast[2] = {0.0, 0.0};
    static double S_slow[2] = {0.0, 0.0};
    static bool initialized[2] = {false, false};
    static uint64_t consecutive_count = 0;
    static uint64_t last_ticks = 0;

    // Step 1: Compute the raw reward R for the completed restart phase
    // R = [log2(conflicts_generated + 1) * 10000] / [(elapsed_ticks + 1) * (avg_LBD * sqrt(avg_trail_level + 1) + 1)]
    const uint64_t conflicts_gen = solver->mab_conflicts;
    const uint64_t current_ticks = solver->ticks;
    const uint64_t elapsed_ticks = (current_ticks > last_ticks) ? (current_ticks - last_ticks) : 0;
    last_ticks = current_ticks;

    // Use Kissat's internal AVERAGE macro to get LBD and trail level averages
    const double avg_lbd = AVERAGE(fast_glue);
    const double avg_trail = AVERAGE(level);
    const double avg_trail_adj = (avg_trail < 0.0) ? 0.0 : avg_trail;

    const double num = log2((double)conflicts_gen + 1.0) * 10000.0;
    const double den = ((double)elapsed_ticks + 1.0) * (avg_lbd * sqrt(avg_trail_adj + 1.0) + 1.0);
    const double R = (den > 0.0) ? (num / den) : 0.0;

    // Step 2: Update dual Exponential Moving Averages (EMA) for the active mode
    const unsigned mode = solver->heuristic;
    if (mode >= 2) return; // Kissat typically uses 0 (stable) and 1 (focused)

    if (!initialized[mode]) {
        S_fast[mode] = S_slow[mode] = R;
        initialized[mode] = true;
    } else {
        S_fast[mode] = 0.8 * S_fast[mode] + 0.2 * R;
        S_slow[mode] = 0.95 * S_slow[mode] + 0.05 * R;
    }

    // Step 3: Calculate the Performance Trend T
    const double T = S_fast[mode] - S_slow[mode];

    // Step 4: Calculate the Fatigue-Adjusted Score S_adj
    // S_adj = S_fast * (0.998 ^ consecutive_count)
    const double S_adj = S_fast[mode] * pow(0.998, (double)consecutive_count);

    // Step 5: Execute mode selection
    const unsigned other = 1 - mode;
    const double S_other_slow = S_slow[other];
    bool switch_mode = false;

    // (a) Switch if S_adj < S_other_slow AND T <= 0
    if (S_adj < S_other_slow && T <= 0.0) {
        switch_mode = true;
    }
    // (b) Switch if T < -0.1 * S_slow (significant decay) and random check
    else if (T < -0.1 * S_slow[mode]) {
        const double ratio = fabs(T) / (S_slow[mode] + 1e-9) * 4.0;
        const double prob_limit = (ratio < 0.6) ? ratio : 0.6;
        if (kissat_pick_double(&solver->random) < prob_limit) {
            switch_mode = true;
        }
    }

    // Step 6: Update consecutive_count and mode
    if (switch_mode) {
        solver->heuristic = other;
        consecutive_count = 0;
    } else {
        consecutive_count++;
    }

    // Standard Kissat MAB tracking reset
    solver->mab_conflicts = 0;
    solver->mab_decisions = 0;
    solver->mab_chosen_tot = 0;
    for (all_variables(idx)) {
        solver->mab_chosen[idx] = 0;
    }
}
